      topic,
      collections,
      objects,
      entities,
      facts: {
        schema: snapshot.profile.schema_id,
        topic: {
          id: snapshot.topicId,
          status: snapshot.profile.status,
          last_verified: snapshot.profile.last_verified,
          source_boundary: snapshot.profile.source_boundary,
        },
      },
      source: snapshot.source,
